tool.command:

  ln -f -s ${input_graph_path} ${input_graph_path}_`echo $$`.${input_graph_path.ext};

#if $config.sele == "option1":
    ln -s -f ${config.properties} ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

shortest_paths

#if $config.sele == "option1":
    --config ${config.properties}_`echo $$`.${config.properties.ext}
  #else if $config.sele == "option2":
    --config '${config.jsonstr}'
  #else if $config.sele == "option3":
    --config '__oc____dq__properties__dq__:__oc____dq__source_residue__dq__:${properties.source_residue},__dq__sink_residue__dq__:${properties.sink_residue},__dq__num_paths__dq__:${properties.num_paths},__dq__weight__dq__:__dq__${properties.weight}__dq__,__dq__method__dq__:__dq__${properties.method}__dq__,__dq__remove_tmp__dq__:${properties.remove_tmp},__dq__restart__dq__:${properties.restart}__cc____cc__'
  #end if

  #if str($input_graph_path) != 'None':
    --input_graph_path ${input_graph_path}_`echo $$`.${input_graph_path.ext}
  #end if


  --output_shortest_paths_path $outname_output_shortest_paths_path
;
#if $config.sele == "option1":
    rm -f ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

  rm -f ${input_graph_path}_`echo $$`.${input_graph_path.ext};


  if test -f $outname_output_shortest_paths_path; then mv $outname_output_shortest_paths_path $output_shortest_paths_path; fi;
